from fractions import Fraction

def primes_up_to(n):
    sieve = [True] * (n + 1)
    for x in range(2, int(math.sqrt(n)) + 1):
        if sieve[x]:
            for i in range(x*x, n + 1, x):
                sieve[i] = False
    return [x for x in range(2, n + 1) if sieve[x]]

def random_tree(width, height):
    if height == 0:
        return []
    children = [random_tree(random.randint(1, width), height - 1) for _ in range(random.randint(1, width))]
    return [(children[0], children[1])] + children[2:]

def deligne_lusztig_cone(tree):
    if not tree:
        return 0
    nodes = set()
    def traverse(node):
        if isinstance(node, tuple):
            nodes.add(node)
            traverse(node[0])
            traverse(node[1])
        else:
            for n in node:
                nodes.add(n)
    traverse(tree)
    rank = len(nodes)
    return rank

def min_rank(tree):
    rank = deligne_lusztig_cone(tree)
    return rank

def run_trial(seed: int) -> dict:
